@Component("bankAccount-handler")
@ProcessingGroup("bankAccount-processing-group")
public class BankAccountEventHandler {
	
	// core constructor
	BankAccountEventHandler(EntityManager entityManager) {
        this.entityManager = entityManager;
    }	
	
    /*
     * @param	event CreateBankAccountEvent
     */
    @EventHandler
    public void handle( CreateBankAccountEvent event) {
        entityManager.persist(new BankAccount(event.getBankAccountId(), event.getAccountHolder(), event.getBankName(), event.getIban(), event.getBic(), event.getAccountNumber(), event.getRoutingNumber()));
    }

    /*
     * @param	event UpdateBankAccountEvent
     */
    @EventHandler
    public BankAccount handle( UpdateBankAccountEvent event) {
    	entityManager.merge(new BankAccount(event.getBankAccountId(), event.getAccountHolder(), event.getBankName(), event.getIban(), event.getBic(), event.getAccountNumber(), event.getRoutingNumber()));
    }
    
    /*
     * @param	event DeleteBankAccountEvent
     */
    @EventHandler
    public void on( DeleteBankAccountEvent event) {
    	BankAccount entity = new BankAccount();
   
    	// ------------------------------------------
    	// apply the BankAccountId
    	// ------------------------------------------
    	entity.setBankAccountId( event.getBankAccountId() );
    	
    	// ------------------------------------------
    	// add to an Iterable and delete
    	// ------------------------------------------
    	entityManager.remove( entity );
    }    
    
    // attributes
	private final BankAccountRepository bankAccountEntityRepository;
    private static final Logger LOGGER 			= Logger.getLogger(BankAccountEventHandler.class.getName());

}
